CREATE OR REPLACE FUNCTION public.shop_crm_order_snapshot(_order_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
 SELECT jsonb_build_object('order', jsonb_build_object('id',o.id,'order_number',o.order_number,'channel',o.channel,'status',o.status,'total',o.total,'currency',o.currency,'stars_total',o.stars_total,'updated_at',o.updated_at,'created_at',o.created_at,'profile_id',o.profile_id,'customer_user_id',o.customer_user_id,'customer_external_id',o.customer_external_id,'customer_first_seen_at',o.customer_first_seen_at,'customer_name',o.customer_name,'delivery_emails',o.delivery_emails,'telegram_user_id',o.telegram_user_id,'telegram_username',p.telegram_username,'payment_method_name',o.payment_method_name,'payment_reference',o.payment_reference,'confirmed_at',o.confirmed_at,'delivered_at',o.delivered_at,'has_payment_proof',(COALESCE(o.payment_evidence_url,'')<>''),'proof_submitted_at',CASE WHEN COALESCE(o.payment_evidence_url,'')<>'' THEN o.submitted_at END), 'items', COALESCE((SELECT jsonb_agg(jsonb_build_object('product_name',i.product_name,'quantity',i.quantity,'snapshot',jsonb_build_object('price_usdt',i.snapshot->'price_usdt'))) FROM public.shop_order_items i WHERE i.order_id=o.id), '[]'::jsonb), 'has_fulfillment', EXISTS(SELECT 1 FROM public.shop_fulfillments f WHERE f.order_id=o.id)) FROM public.shop_orders o LEFT JOIN public.profiles p ON p.id=o.profile_id WHERE o.id=_order_id;
$$;
REVOKE ALL ON FUNCTION public.shop_crm_order_snapshot(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.shop_crm_order_snapshot(uuid) TO service_role;
UPDATE public.shop_orders SET updated_at = now() WHERE COALESCE(payment_evidence_url,'') <> '';